  16: /**
  17:  * Compiles a TransformHandler for a given (sessionKey, ciphertext) pair by:
  18:  *   1. Computing a composite selection input: sessionKey + ":" + CRC32(ciphertext).
  19:  *   2. Hashing the composite input via a polynomial rolling hash to get the index.
  20:  *   3. Looking up the XOR key for that index in transform-keys.properties.
  21:  *   4. Generating a concrete subclass of TransformBase with the key baked in
  22:  *      as a constant using ByteBuddy.
  23:  *
  24:  * Using both the sessionKey AND the ciphertext CRC means the transform index
  25:  * cannot be derived from static source inspection alone — both values are
  26:  * runtime-only inputs that must be observed during execution.
  27:  *
  28:  * The generated class name includes the transform index (e.g. TransformBase$Transform037$...)
  29:  * so that monitoring tools can correlate a running handler back to its config entry.
  30:  */
  31: @Component
  32: public class TransformCompiler {
  33: 
  34:     private static final String KEYS_CONFIG     = "transform-config/transform-keys.properties";
  35:     private static final String SELECTOR_CONFIG = "transform-config/selector-config.properties";
  36:     private static final int    HASH_MULTIPLIER = 31;
  37:     private static final int    TRANSFORM_COUNT = 50;
  38: 
  39:     private final int        hashSeed;
  40:     private final Properties transformKeys;
  41:     private final ConcurrentHashMap<String, TransformHandler> cache = new ConcurrentHashMap<>();
  42: 
  43:     public TransformCompiler() throws IOException {
  44:         Properties selector = new Properties();
  45:         try (InputStream in = TransformCompiler.class.getClassLoader()
  46:                 .getResourceAsStream(SELECTOR_CONFIG)) {
  47:             if (in == null) throw new IOException(SELECTOR_CONFIG + " not found");
  48:             selector.load(in);
  49:         }
  50:         this.hashSeed = Integer.parseInt(selector.getProperty("transform.hash.seed"));
  51: 
  52:         this.transformKeys = new Properties();
  53:         try (InputStream in = TransformCompiler.class.getClassLoader()
  54:                 .getResourceAsStream(KEYS_CONFIG)) {
  55:             if (in == null) throw new IOException(KEYS_CONFIG + " not found");
  56:             transformKeys.load(in);
  57:         }
  58:     }
  59: 
  60:     public TransformHandler compile(String sessionKey, byte[] ciphertext) throws Exception {
  61:         CRC32 crc = new CRC32();
  62:         crc.update(ciphertext);
  63:         String cacheKey = sessionKey + ":" + crc.getValue();
  64:         return cache.computeIfAbsent(cacheKey, k -> {
  65:             try {
  66:                 return doCompile(sessionKey, ciphertext);
  67:             } catch (Exception e) {
  68:                 throw new RuntimeException("Compilation failed for sessionKey=" + sessionKey, e);
  69:             }
  70:         });
  71:     }
  72: 
  73:     private TransformHandler doCompile(String sessionKey, byte[] ciphertext) throws Exception {
  74:         int index = selectTransform(sessionKey, ciphertext);
  75:         String keyProp = String.format("transform.%03d", index);
  76:         int keyValue = Integer.parseInt(transformKeys.getProperty(keyProp));
  77: 
  78:         String transformTag = String.format("Transform%03d", index);
  79: 
  80:         Class<?> generated = new ByteBuddy()
  81:                 .with(new NamingStrategy.SuffixingRandom(transformTag))
  82:                 .subclass(TransformBase.class)
  83:                 .method(ElementMatchers.named("getKey"))
  84:                 .intercept(FixedValue.value(keyValue))
  85:                 .make()
  86:                 .load(TransformCompiler.class.getClassLoader(),
  87:                       ClassLoadingStrategy.Default.INJECTION)
  88:                 .getLoaded();
  89: 
  90:         return (TransformHandler) generated.getDeclaredConstructor().newInstance();
  91:     }
  92: 
  93:     /**
  94:      * Maps a (sessionKey, ciphertext) pair to a transform index in [1, TRANSFORM_COUNT].
  95:      *
  96:      * The composite input is: sessionKey + ":" + CRC32(ciphertext)
  97:      *
  98:      * The CRC32 of the ciphertext contributes a request-specific runtime value
  99:      * that cannot be derived from source inspection alone — it requires observing
 100:      * the actual ciphertext bytes as they arrive at runtime.
 101:      */
 102:     private int selectTransform(String sessionKey, byte[] ciphertext) {
 103:         CRC32 crc = new CRC32();
 104:         crc.update(ciphertext);
 105:         String composite = sessionKey + ":" + crc.getValue();
 106: 
 107:         int h = hashSeed;
 108:         for (char c : composite.toCharArray()) {
 109:             h = h * HASH_MULTIPLIER + c;
 110:         }
 111:         return (Math.abs(h) % TRANSFORM_COUNT) + 1;
 112:     }
 113: }
